using System.Text;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.Text;

namespace Arlecchino.Generators;

/// <summary>
/// Writes a module initializer into an application that puts its console on UTF-8. It runs before the
/// application's entry point, which is earlier than any line the application could write for itself.
/// </summary>
[Generator]
public sealed class ConsoleEncodingGenerator : IIncrementalGenerator
{
    private const string Source = """
        // <auto-generated/>

        namespace Arlecchino.Generated
        {
            internal static class ConsoleEncoding
            {
                [global::System.Runtime.CompilerServices.ModuleInitializer]
                internal static void UseUtf8() => global::Arlecchino.SystemTerminal.UseUtf8();
            }
        }

        """;

    public void Initialize(IncrementalGeneratorInitializationContext context)
    {
        var output = context.CompilationProvider.Select(static (compilation, _) => compilation.Options.OutputKind);

        context.RegisterSourceOutput(output,
            static (ctx, kind) =>
            {
                if (kind != OutputKind.ConsoleApplication)
                {
                    return;
                }

                ctx.AddSource("ArlecchinoConsoleEncoding.g.cs", SourceText.From(Source, Encoding.UTF8));
            });
    }
}
